-- HORIBA (new brand): LAQUAtwin waterproof pocket water quality meters (13 models) and
-- LAQUA 2000 Series benchtop meters PH2000, EC2000, ION2000, DO2000, PC2000, PD2000 (20 meter kits).
-- From the HORIBA LAQUAtwin and LAQUA 2000 Series brochures. Photos: public/products/horiba/, logo: public/brands/horiba.png.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('HORIBA', 'horiba', 'https://www.horiba.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('HORIBA-LAQUATWIN-PH-11', 'HORIBA LAQUAtwin pH-11 pH Pocket Meter', 'horiba-laquatwin-ph-11-ph-pocket-meter', 'The HORIBA LAQUAtwin pH-11 is a compact, IP67 waterproof ph pocket meter with HORIBA''s flat sensor, so a single drop of sample is enough. Made in Japan. Supplied with pH 7.00 and 4.01 buffers (14 mL each), CR2032 batteries (2), dropper, manuals and storage case.', '[["Model", "pH-11"], ["Part no.", "3999960122"], ["pH range / resolution", "0.0 to 14.0 pH / 0.1 pH"], ["Accuracy", "±0.1 pH"], ["Calibration points", "Up to 2"], ["Principle", "Glass electrode, flat glass sensor"], ["Min. sample", "0.1 mL (0.05 mL with sampling sheet B)"], ["mV range", "-650 to 650 mV / 1 mV"], ["Calibration buffers", "USA: 1.68, 4.01, 7.00, 10.01, 12.46; NIST: 1.68, 4.01, 6.86, 9.18, 12.46"], ["Functions", "Automatic buffer recognition, temperature compensation"], ["Supplied with", "PH 7.00 and 4.01 buffers (14 mL each), 2 × CR2032 batteries, dropper, manuals, storage case"], ["Display", "Custom monochrome digital LCD with backlight"], ["Operating conditions", "5 to 40 °C, ≤ 85 % RH (no condensation)"], ["Battery life", "Approx. 400 h continuous use without backlight (2 × CR2032)"], ["Protection", "IP67 waterproof and dustproof"], ["Dimensions", "164 × 29 × 20 mm (excluding projections)"], ["Warranty", "2 years"], ["Made in", "Japan"]]', '["Measures from a single drop: as little as 0.1 mL (0.05 mL with sampling sheet B)", "Flat sensor: test liquids, solids, powders, paper and films, or scoop and immerse", "One-button calibration and measurement; smiley face shows a stable reading", "IP67 waterproof and dustproof, with backlit display", "Replaceable sensor", "Auto Hold / Auto Stable, auto power-off (30 min), low battery indicator", "Comes in a carrying case with calibration solutions"]', 'environmental-equipment', '/products/horiba/laquatwin-ph.jpg'),
  ('HORIBA-LAQUATWIN-PH-22', 'HORIBA LAQUAtwin pH-22 pH Pocket Meter', 'horiba-laquatwin-ph-22-ph-pocket-meter', 'The HORIBA LAQUAtwin pH-22 is a compact, IP67 waterproof ph pocket meter with HORIBA''s flat sensor, so a single drop of sample is enough. Made in Japan. Supplied with pH 7.00 and 4.01 buffers (14 mL each), CR2032 batteries (2), dropper, manuals and storage case.', '[["Model", "pH-22"], ["Part no.", "3999960123"], ["pH range / resolution", "0.00 to 14.00 pH / 0.01 pH"], ["Accuracy", "±0.01 pH"], ["Calibration points", "Up to 3"], ["Principle", "Glass electrode, flat glass sensor"], ["Min. sample", "0.1 mL (0.05 mL with sampling sheet B)"], ["mV range", "-650 to 650 mV / 1 mV"], ["Calibration buffers", "USA: 1.68, 4.01, 7.00, 10.01, 12.46; NIST: 1.68, 4.01, 6.86, 9.18, 12.46"], ["Functions", "Automatic buffer recognition, temperature compensation"], ["Supplied with", "PH 7.00 and 4.01 buffers (14 mL each), 2 × CR2032 batteries, dropper, manuals, storage case"], ["Display", "Custom monochrome digital LCD with backlight"], ["Operating conditions", "5 to 40 °C, ≤ 85 % RH (no condensation)"], ["Battery life", "Approx. 400 h continuous use without backlight (2 × CR2032)"], ["Protection", "IP67 waterproof and dustproof"], ["Dimensions", "164 × 29 × 20 mm (excluding projections)"], ["Warranty", "2 years"], ["Made in", "Japan"]]', '["Measures from a single drop: as little as 0.1 mL (0.05 mL with sampling sheet B)", "Flat sensor: test liquids, solids, powders, paper and films, or scoop and immerse", "One-button calibration and measurement; smiley face shows a stable reading", "IP67 waterproof and dustproof, with backlit display", "Replaceable sensor", "Auto Hold / Auto Stable, auto power-off (30 min), low battery indicator", "Comes in a carrying case with calibration solutions"]', 'environmental-equipment', '/products/horiba/laquatwin-ph.jpg'),
